import * as $c from '../crt/index.js';
import * as $T from './types.js';
import { $G } from './globals.js';
import { db_under_typ } from './dbridge.js';
import { iflags, svl } from './decl.js';
import { S } from './defsym.h.js';
import { AIR, ALTAR, CLOUD, DBWALL, DOOR, DRAWBRIDGE_DOWN, DRAWBRIDGE_UP, FOUNTAIN, F_LOOTED, F_WARNED, GRAVE, LADDER, LAVAPOOL, LAVAWALL, POOL, ROOM, SDOOR, SINK, STAIRS, STONE, THRONE, TREE, WATER } from './rm.h.js';

export function IS_WALL(typ) {
    return typ && typ <= DBWALL ? 1 : 0;
}
export function IS_STWALL(typ) {
    return typ <= DBWALL ? 1 : 0;
}
export function IS_OBSTRUCTED(typ) {
    return typ < POOL ? 1 : 0;
}
export function IS_SDOOR(typ) {
    return typ === SDOOR ? 1 : 0;
}
export function IS_DOOR(typ) {
    return typ === DOOR ? 1 : 0;
}
export function IS_TREE(typ) {
    return typ === TREE || svl.level.flags.arboreal && typ === STONE ? 1 : 0;
}
export function ACCESSIBLE(typ) {
    return typ >= DOOR ? 1 : 0;
}
export function IS_ROOM(typ) {
    return typ >= ROOM ? 1 : 0;
}
export function ZAP_POS(typ) {
    return typ >= POOL ? 1 : 0;
}
export function SPACE_POS(typ) {
    return typ > DOOR ? 1 : 0;
}
export function IS_POOL(typ) {
    return typ >= POOL && typ <= DRAWBRIDGE_UP ? 1 : 0;
}
export function IS_LAVA(typ) {
    return typ === LAVAPOOL || typ === LAVAWALL ? 1 : 0;
}
export function IS_THRONE(typ) {
    return typ === THRONE ? 1 : 0;
}
export function IS_FOUNTAIN(typ) {
    return typ === FOUNTAIN ? 1 : 0;
}
export function IS_SINK(typ) {
    return typ === SINK ? 1 : 0;
}
export function IS_GRAVE(typ) {
    return typ === GRAVE ? 1 : 0;
}
export function IS_ALTAR(typ) {
    return typ === ALTAR ? 1 : 0;
}
export function IS_DRAWBRIDGE(typ) {
    return typ === DRAWBRIDGE_UP || typ === DRAWBRIDGE_DOWN ? 1 : 0;
}
export function IS_FURNITURE(typ) {
    return typ >= STAIRS && typ <= ALTAR ? 1 : 0;
}
export function IS_AIR(typ) {
    return typ === AIR || typ === CLOUD ? 1 : 0;
}
export function IS_WATERWALL(typ) {
    return typ === WATER ? 1 : 0;
}
export function SURFACE_AT(x, y) {
    return svl.level.locations[x][y].typ === DRAWBRIDGE_UP ? db_under_typ(svl.level.locations[x][y].flags) : svl.level.locations[x][y].typ;
}
export function FOUNTAIN_IS_WARNED(x, y) {
    return svl.level.locations[x][y].flags & F_WARNED;
}
export function FOUNTAIN_IS_LOOTED(x, y) {
    return svl.level.locations[x][y].flags & F_LOOTED;
}
export function CAN_OVERWRITE_TERRAIN(ttyp) {
    return iflags.debug_overwrite_stairs || !(ttyp === LADDER || ttyp === STAIRS) ? 1 : 0;
}
export function fmon() {
    return svl.level.monlist;
}
export function trap_to_defsym(t) {
    return (S.arrow_trap + t | 0) - 1 | 0;
}
export function OBJ_AT(x, y) {
    return svl.level.objects[x][y] !== null ? 1 : 0;
}
export function MON_AT(x, y) {
    return svl.level.monsters[x][y] !== null ? 1 : 0;
}
export function m_at(x, y) {
    return svl.level.monsters[x][y];
}
export function remove_monster(x, y) {
    return svl.level.monsters[x][y] = null;
}
export function Sokoban() {
    return svl.level.flags.sokoban_rules;
}
